import fs from "node:fs";
import path from "node:path";
import { getConfig } from "./config";

/**
 * Storage keys are generated by the server ("uploads/<id>.mp4") and never
 * derived from user filenames. The local driver maps them under the data
 * directory; an S3-compatible driver can implement the same interface later.
 */
export interface StorageDriver {
  absolutePath(key: string): string;
  exists(key: string): boolean;
  size(key: string): number;
  remove(key: string): void;
  ensureDir(prefix: string): string;
}

const KEY_PATTERN = /^(uploads|outputs|thumbs|tmp|kit)\/[A-Za-z0-9_.-]+$/;

class LocalStorage implements StorageDriver {
  constructor(private root: string) {}

  absolutePath(key: string) {
    if (!KEY_PATTERN.test(key) || key.includes("..")) throw new Error("Invalid storage key");
    return path.join(/*turbopackIgnore: true*/ this.root, key);
  }
  exists(key: string) {
    return fs.existsSync(this.absolutePath(key));
  }
  size(key: string) {
    return fs.statSync(this.absolutePath(key)).size;
  }
  remove(key: string) {
    fs.rmSync(this.absolutePath(key), { force: true, recursive: true });
  }
  ensureDir(prefix: string) {
    const dir = path.join(/*turbopackIgnore: true*/ this.root, prefix);
    fs.mkdirSync(dir, { recursive: true });
    return dir;
  }
}

export function getStorage(): StorageDriver {
  return new LocalStorage(getConfig().dataDir);
}

export async function freeDiskBytes(): Promise<number> {
  const dir = getConfig().dataDir;
  fs.mkdirSync(dir, { recursive: true });
  const s = await fs.promises.statfs(dir);
  return s.bavail * s.bsize;
}

export function storageBytesUsed(): number {
  const root = getConfig().dataDir;
  let total = 0;
  for (const sub of ["uploads", "outputs", "thumbs", "kit"]) {
    const dir = path.join(/*turbopackIgnore: true*/ root, sub);
    if (!fs.existsSync(dir)) continue;
    for (const f of fs.readdirSync(dir)) total += fs.statSync(path.join(/*turbopackIgnore: true*/ dir, f)).size;
  }
  return total;
}
